export const getResetPasswordCallbackUrl = (token: string,
    params: ResetPasswordCallbackParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `${process.env.EXPO_PUBLIC_BACKEND_BASE_URL ?? 'http://localhost:3000'}/api/auth/reset-password/${token}?${stringifiedParams}` : `${process.env.EXPO_PUBLIC_BACKEND_BASE_URL ?? 'http://localhost:3000'}/api/auth/reset-password/${token}`
}

