export const getGetApiAuthErrorUrl = () => {




  return `${process.env.EXPO_PUBLIC_BACKEND_BASE_URL ?? 'http://localhost:3000'}/api/auth/error`
}

/**
 * Displays an error page
 */
export const getApiAuthError = async ( options?: Parameters<typeof f>[1]): Promise<getApiAuthErrorResponse> => {

  return f<getApiAuthErrorResponse>(getGetApiAuthErrorUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





